import type { Metadata } from 'next';
import { LOCALES, OG_LOCALE, DEFAULT_LOCALE, localizePath, type Locale } from '@/i18n/config';

// Single source of truth for absolute URLs and shared SEO values.
export const SITE_URL = 'https://daelijek-portfolio.vercel.app';
export const SITE_NAME = 'Dias Yermek Portfolio';

export interface OgImage {
  url: string;
  width: number;
  height: number;
  alt: string;
}

// 1200x630 previews generated by scripts/generate-og.mjs
export const DEFAULT_OG_IMAGE: OgImage = {
  url: '/og/default.jpg',
  width: 1200,
  height: 630,
  alt: 'Dias Yermek — Middle Frontend & Mobile Developer',
};

export const projectOgImage = (slug: string, title: string): OgImage => ({
  url: `/og/${slug}.jpg`,
  width: 1200,
  height: 630,
  alt: `${title} — case study by Dias Yermek`,
});

export const absoluteUrl = (path = '/'): string => new URL(path, SITE_URL).toString();

/** canonical + hreflang alternates for a locale-free `path`. */
export function alternatesFor(path: string, locale: Locale): NonNullable<Metadata['alternates']> {
  const languages: Record<string, string> = Object.fromEntries(LOCALES.map((l) => [l, localizePath(path, l)]));
  languages['x-default'] = localizePath(path, DEFAULT_LOCALE);
  return { canonical: localizePath(path, locale), languages };
}

/** Page metadata with canonical, hreflang, OpenGraph and Twitter card in one place. */
export function pageMetadata({
  locale,
  path,
  title,
  description,
  image = DEFAULT_OG_IMAGE,
  type = 'website',
  keywords,
}: {
  locale: Locale;
  path: string;
  title: string;
  description: string;
  image?: OgImage;
  type?: 'website' | 'article';
  keywords?: string[];
}): Metadata {
  return {
    title,
    description,
    keywords,
    alternates: alternatesFor(path, locale),
    openGraph: {
      title,
      description,
      url: localizePath(path, locale),
      siteName: SITE_NAME,
      images: [image],
      locale: OG_LOCALE[locale],
      alternateLocale: LOCALES.filter((l) => l !== locale).map((l) => OG_LOCALE[l]),
      type,
    },
    twitter: {
      card: 'summary_large_image',
      title,
      description,
      images: [image.url],
    },
  };
}
